func main() {
    reader := bufio.NewReaderSize(os.Stdin, 16 * 1024 * 1024)

    stdout, err := os.Create(os.Getenv("OUTPUT_PATH"))
    checkError(err)

    defer stdout.Close()

    writer := bufio.NewWriterSize(stdout, 16 * 1024 * 1024)

    firstMultipleInput := strings.Split(strings.TrimSpace(readLine(reader)), " ")

    nTemp, err := strconv.ParseInt(firstMultipleInput[0], 10, 64)
    checkError(err)
    n := int32(nTemp)

    mTemp, err := strconv.ParseInt(firstMultipleInput[1], 10, 64)
    checkError(err)
    m := int32(mTemp)

    var paths [][]int32
    for i := 0; i < int(m); i++ {
        pathsRowTemp := strings.Split(strings.TrimRight(readLine(reader)," \t\r\n"), " ")

        var pathsRow []int32
        for _, pathsRowItem := range pathsRowTemp {
            pathsItemTemp, err := strconv.ParseInt(pathsRowItem, 10, 64)
            checkError(err)
            pathsItem := int32(pathsItemTemp)
            pathsRow = append(pathsRow, pathsItem)
        }

        if len(pathsRow) != 2 {
            panic("Bad input")
        }

        paths = append(paths, pathsRow)
    }

    qTemp, err := strconv.ParseInt(strings.TrimSpace(readLine(reader)), 10, 64)
    checkError(err)
    q := int32(qTemp)

    for qItr := 0; qItr < int(q); qItr++ {
        queryCount, err := strconv.ParseInt(strings.TrimSpace(readLine(reader)), 10, 64)
        checkError(err)

        queryTemp := strings.Split(strings.TrimSpace(readLine(reader)), " ")

        var query []int32

        for i := 0; i < int(queryCount); i++ {
            queryItemTemp, err := strconv.ParseInt(queryTemp[i], 10, 64)
            checkError(err)
            queryItem := int32(queryItemTemp)
            query = append(query, queryItem)
        }

        result := bendersPlay(n, paths, query)

        fmt.Fprintf(writer, "%s\n", result)
    }

    writer.Flush()
}

func readLine(reader *bufio.Reader) string {
    str, _, err := reader.ReadLine()
    if err == io.EOF {
        return ""
    }

    return strings.TrimRight(string(str), "\r\n")
